public int findLargestSubstring(List<String> strings) {
    int largestSubstring = -1;
    for (String str : strings) {
        int currSubstring = str.length();
        for (String otherStr : strings) {
            if (!str.equals(otherStr)) {
                int index = otherStr.indexOf(str);
                if (index != -1) {
                    currSubstring = Math.min(currSubstring, otherStr.length() - index);
                }
            }
        }
        largestSubstring = Math.max(largestSubstring, currSubstring);
    }
    return largestSubstring;
