public static int countOilDeposits(char[][] grid) {
    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                dfs(grid, i, j, '@');
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, int i, int j, char current) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != current) {
        return;
    }

    grid[i][j] = '@';
    dfs(grid, i + 1, j, '@');
    dfs(grid, i - 1, j, '@');
    dfs(grid, i, j + 1, '@');
    dfs(grid, i, j - 1, '@');
}
