public static int maxRegions(int N) {
    if (N == 1) {
        return 2;
    } else if (N == 2) {
        return 8;
    }
    int[] dp = new int[N];
    for (int i = 3; i <= N; i++) {
        dp[i-1] = 2 * (i-1) * dp[i-2] + (i-2) * (i-2) * dp[i-3];
    }
    return dp[N-1];
}
