import java.util.Arrays;
import java.util.Set;
import java.util.HashSet;

public class Maze {
    public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        // Initialize a set to store the visited n-tersections
        Set<Integer> visited = new HashSet<>();

        // Add the starting n-tersection to the visited set
        visited.add(start[0]);

        // Initialize a queue to store the n-tersections to be explored
        Queue<Integer> queue = new LinkedList<>();

        // Add the starting n-tersection to the queue
        queue.offer(start[0]);

        // Loop until the queue is empty or the ending n-tersection is reached
        while (!queue.isEmpty()) {
            // Get the current n-tersection from the queue
            int ntersection = queue.poll();

            // If the current n-tersection is the ending n-tersection, return "can be travelled"
            if (Arrays.equals(ntersection, end)) {
                return "can be travelled";
            }

            // Add the current n-tersection to the visited set
            visited.add(ntersection);

            // Get the paths connected to the current n-tersection
            for (int[] path : paths) {
                // If the path is not visited, add it to the queue
                if (!visited.contains(path[0]) && path[0] != ntersection) {
                    queue.offer(path[0]);
                }

                // If the path is not visited, add it to the queue
                if (!visited.contains(path[1]) && path[1] != ntersection) {
                    queue.offer(path[1]);
                }
            }
        }

        // Return "cannot be travelled" if the ending n-tersection is not reached
        return "cannot be travelled";
    }
}
