    } else if (month < 8) {
        days = (month % 2 == 0) ? 30 : 31;
    } else if (month > 7) {
        days = (month % 2 == 1) ? 30 : 31;
    }

    return (day + year + (year / 4) - (year / 100) + (year / 400)) % 7;
