public double trimMean(int[] arr) {
    // Calculate the number of elements to remove from the smallest and largest 5% of the array
    int removeSmallest = (int) Math.ceil(arr.length * 0.05);
    int removeLargest = (int) Math.ceil(arr.length * 0.05);

    // Use quickselect to find the kth smallest element
    int kthSmallest = kthSmallest(arr, removeSmallest + 1);
    int kthLargest = kthLargest(arr, arr.length - removeLargest);

    // Remove the smallest and largest elements
    List<Integer> filteredArr = Arrays.stream(arr).boxed().filter(x -> x != kthSmallest && x != kthLargest).collect(Collectors.toList());

    // Calculate the mean of the remaining elements
    double mean = filteredArr.stream().mapToInt(x -> x).average().getAsDouble();

    return mean;
}

// Quickselect algorithm to find the kth smallest element
private static int kthSmallest(int[] arr, int k) {
    int start = 0;
    int end = arr.length - 1;

    while (start < end) {
        int pivotIndex = partition(arr, start, end);

        if (pivotIndex == k - 1) {
            return arr[pivotIndex];
        } else if (pivotIndex > k - 1) {
            end = pivotIndex - 1;
        } else {
            start = pivotIndex + 1;
        }
    }

    return arr[start];
}

// Quickselect algorithm to find the kth largest element
private static int kthLargest(int[] arr, int k) {
    int start = 0;
    int end = arr.length - 1;

    while (start < end) {
        int pivotIndex = partition(arr, start, end);

        if (pivotIndex == arr.length - k) {
            return arr[pivotIndex];
        } else if (pivotIndex < arr.length - k) {
            start = pivotIndex + 1;
        } else {
            end = pivotIndex - 1;
        }
    }

    return arr[end];
}

// Partition the array using the Lomuto partition scheme
private static int partition(int[] arr, int start, int end) {
    int pivot = arr[end];
    int partitionIndex = start;

    for (int i = start; i < end; i++) {
        if (arr[i] <= pivot) {
            swap(arr, i, partitionIndex);
            partitionIndex++;
        }
    }

    swap(arr, partitionIndex, end);

    return partitionIndex;
}

// Swap two elements in the array
private static void swap(int[] arr, int i, int j) {
    int tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
}
