import java.util.ArrayList;
import java.util.List;

public class MinTime {

    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<Boolean> visited = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            visited.add(false);
        }
        int appleCount = 0;
        for (int i = 0; i < n; i++) {
            if (hasApple[i]) {
                appleCount++;
                visited.set(i, true);
            }
        }
        // Only one apple and it is at node 0.
        if (appleCount == 1 && visited.get(0)) {
            return 0;
        }
        // All nodes have apples.
        if (appleCount == n) {
            return 1;
        }
        // Check if all the apples are at nodes that are reachable from node 0.
        // If they are, we only need to go back to node 0 once.
        boolean allApplesReachable = true;
        for (int i = 0; i < n; i++) {
            if (hasApple[i]) {
                allApplesReachable &= checkReachable(i, 0, visited);
            }
        }
        if (allApplesReachable) {
            return 1;
        }
        // Go through each edge and find the minimum time required to collect all the apples.
        int minTime = Integer.MAX_VALUE;
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < n; j++) {
                visited.set(j, false);
            }
            minTime = Math.min(minTime, dfs(edges[i][0], edges[i][1], visited, hasApple, 1));
        }
        return minTime;
    }

    private int dfs(int curr, int dest, List<Boolean> visited, boolean[] hasApple, int time) {
        if (curr == dest) {
            return time;
        }
        visited.set(curr, true);
        if (hasApple[curr]) {
            time++;
        }
        for (int i = 0; i < visited.size(); i++) {
            if (visited.get(i)) {
                continue;
            }
            int newTime = dfs(i, dest, visited, hasApple, time + 1);
            if (newTime != Integer.MAX_VALUE) {
                time = newTime;
                break;
            }
        }
        visited.set(curr, false);
        return time;
    }

    private boolean checkReachable(int curr, int dest, List<Boolean> visited) {
        if (curr == dest) {
            return true;
        }
        visited.set(curr, true);
        for (int i = 0; i < visited.size(); i++) {
            if (visited.get(i)) {
                continue;
            }
            if (checkReachable(i, dest, visited)) {
                return true;
            }
        }
        visited.set(curr, false);
        return false;
    }
}
