    // diagonal
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int currentLength = 0;
            int ii = i;
            int jj = j;
            while (ii >= 0 && jj >= 0 && ii < m && jj < n && mat[ii][jj] == 1) {
                currentLength++;
                ii++;
                jj++;
            }
            maxLength = Math.max(maxLength, currentLength);
        }
    }

    // anti-diagonal
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            int currentLength = 0;
