public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dp[i][j] = -1;
        }
    }
    return solve(A, 0, n-1, dp);
}

private static int solve(int[] A, int i, int j, int[][] dp) {
    if (i == j) {
        return 1;
    }
    if (dp[i][j] != -1) {
        return dp[i][j];
    }
    int count = 0;
    for (int k = i; k <= j-1; k++) {
        int sum = A[i] + A[k];
        if (isPerfectSquare(sum)) {
            count += solve(A, i+1, k-1, dp) * solve(A, k+1, j, dp);
        }
    }
    dp[i][j] = count;
    return count;
}

private static boolean isPerfectSquare(int n) {
    double root = Math.sqrt(n);
    return root == Math.floor(root);
}
